pub fn build(h: Rc<Array<u64>>, sz: u64, k: u64, _H: ()) -> Rc<Array<u64>> {
  let tmp = ltb(0u64, k);
  match bdec(tmp) {
    sumbool::left => {
      let tmp_1 = sift_1(h, sz, sub(k, 1u64));
      build(tmp_1, sz, sub(k, 1u64), ())
    },
    sumbool::right => {
      h
    },
  }
}

